import json
from collections import defaultdict

# Load all records
records = []
for f in sorted([f for f in os.listdir('/app/') if f.endswith('.jsonl')]):
    filepath = f'/app/{f}'
    with open(filepath, 'r') as fh:
        for line in fh:
            line = line.strip()
            if line:
                records.append(json.loads(line))

# Aggregate user totals
user_amount = defaultdict(float)
user_items = defaultdict(int)

# Aggregate tag counts
tag_counts = defaultdict(int)

