top_5_users = {}
for i in range(min(5, len(user_list))):
    total_amount = round(user_list[i][0], 2)
    total_items = user_items[user_list[i][1]]
    top_5_users[user_list[i][1]] = {
        "total_amount": total_amount,
        "total_items": total_items
    }

# Top 5 tags by count
tag_list = []
for tag, count in tag_counts.items():
    tag_list.append((count, tag))
tag_list.sort(key=lambda x: (-x[0], x[1]))
top_5_tags = {}
for i in range(min(5, len(tag_list))):
    top_5_tags[tag_list[i][1]] = {
        "count": tag_list[i][0]
    }

result = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

with open('/app/aggregates.json', 'w') as f:
    json.dump(result, f, indent=2)

